function pCandidates(week,now=Date.now()){
 const result=[];
 if(DartHealth.health(M,now).stale)return result;
 for(const f of M.forecasts){
  if(f.reviewRequired)continue;
  const g=game(f),o=parlayOdds.games[f.id];
  if(!Seabiscuit.eligibleQuote(o,g,now)||pWeek(o.date)!==week)continue;
  const q=forecast(f);
