// Records are derived from saved pregame forecasts, never current predictions.
const DarkhorseResults = (() => {
  const markets = {winner:'Moneyline',spread:'Point spread',total:'Over / under',upset:'Outright upsets'};
  const descriptions = {winner:'Did we pick the winning team?',spread:'Did our side beat the point spread?',total:'Did we pick the right side of the combined score?',upset:'Did our underdog pick win the game?'};
  const easternDate = value => new Intl.DateTimeFormat('en-CA',{timeZone:'America/New_York',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(value));
  function weekOf(value){const d=new Date(easternDate(value)+'T12:00:00Z');d.setUTCDate(d.getUTCDate()-((d.getUTCDay()+6)%7));return d.toISOString().slice(0,10);}
  function outcome(row,key){return key==='upset'?row.upsetPickResult:row[key];}
  function tally(rows,key){const counts={win:0,loss:0,push:0,no_pick:0,unavailable:0};for(const row of rows){const v=outcome(row,key);if(v in counts)counts[v]++;}return counts;}
  function filter(rows,period,conference,query,teams){return rows.filter(r=>(period==='all'||(period.startsWith('week:')?weekOf(r.date)===period.slice(5):easternDate(r.date)===period.slice(4)))&&(conference==='all'||[r.home,r.away].some(t=>teams[t]?.conference===conference))&&(!query||[r.home,r.away].some(t=>(teams[t]?.name||t).toLowerCase().includes(query.toLowerCase()))));}
  const api={tally,filter,weekOf,easternDate};
  if(typeof module!=='undefined')module.exports=api;
  if(typeof document==='undefined')return api;
  let data,market='winner',period='all',conference='all',query='',limit=12;
  const signed=n=>(n>0?'+':'')+Number(n.toFixed(1));
  const niceDate=value=>new Date(value+'T12:00:00Z').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric',timeZone:'UTC'});
  const stamp=value=>new Date(value).toLocaleString('en-US',{timeZone:'America/New_York',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})+' ET';
  const score=r=>`${name(r.away)} ${r.awayScore} · ${name(r.home)} ${r.homeScore}`;
  function selection(r,key){
    if(key==='winner'||key==='upset')return r.pickedTeam?`${name(r.pickedTeam)} to win`:'No winner selected';
    if(key==='spread'){
      if(r.homeSpread==null)return 'No saved point spread';
      const edge=r.predictedHomeMargin+r.homeSpread;
      if(Math.abs(edge)<1e-9)return 'No spread pick';
      return `${name(edge>0?r.home:r.away)} ${signed(edge>0?r.homeSpread:-r.homeSpread)}`;
    }
    if(r.overUnder==null)return 'No saved total';
    if(Math.abs(r.predictedTotal-r.overUnder)<1e-9)return 'No over/under pick';
    return `${r.predictedTotal>r.overUnder?'Over':'Under'} ${r.overUnder}`;
  }
  function metric(rows,key){const c=tally(rows,key),n=c.win+c.loss,rate=n?100*c.win/n:0;return `<button type="button" class="pr-metric" data-pr-market="${key}" aria-pressed="${market===key}"><span class="pr-label">${markets[key]}</span><strong>${c.win}<small> correct</small></strong><span class="pr-record">${c.loss} missed${c.push?' · '+c.push+' pushed':''}</span><span class="pr-bar" aria-hidden="true"><i style="width:${rate}%"></i></span><span class="pr-rate">${n?rate.toFixed(1)+'% of '+n+' decided picks':'No decided picks'}</span><span class="pr-definition">${descriptions[key]}</span></button>`;}
  function upsetCard(r){const picked=r.pickedTeam,opp=picked===r.home?r.away:r.home,ex=r.explanation,winScore=picked===r.home?r.homeScore:r.awayScore,otherScore=picked===r.home?r.awayScore:r.homeScore;
    return `<article class="pr-upset"><div class="pr-upset-top"><span class="pr-hit">OUTRIGHT WIN</span><span>${niceDate(easternDate(r.date))}</span></div><div class="pr-team">${logo(picked)}<div><h3>${esc(name(picked))} <span>+${Math.abs(r.homeSpread)}</span></h3><p>${r.neutral?'Neutral site':picked===r.home?'Home underdog':'Road underdog'} vs. ${esc(name(opp))}</p></div></div><div class="pr-final"><b>${winScore} <span>–</span> ${otherScore}</b><span>FINAL · ${esc(name(picked))} won</span></div><div class="pr-saved"><span>Our saved pick</span><b>${esc(name(picked))} to win</b><small>By ${Math.abs(r.predictedHomeMargin).toFixed(1)} points${r.pickWinProbability!=null?' · '+(r.pickWinProbability*100).toFixed(1)+'% win chance':''}</small></div><h4>Why we picked it</h4><p>${esc(ex?.pregame||'The saved forecast favored this team. Detailed input contributions were not archived.')}</p><h4>What happened</h4>${(ex?.recap||['The final score confirms the outright win.']).map(t=>`<p>${esc(t)}</p>`).join('')}<details class="pr-evidence"><summary>See the pick’s evidence</summary><p>Pick saved ${esc(stamp(r.forecastAt))}. ${r.archiveType==='recovered_saved_forecast'?'Recovered from an older saved forecast file.':'Archived by the daily updater.'}</p><p>Underdog label comes from the saved spread, checked ${esc(stamp(r.quoteRetrievedAt))}${r.quoteProvider?' · '+esc(r.quoteProvider):''}.</p>${ex?.drivers?.length?`<p>Points toward ${esc(name(picked))}; negative values favored the opponent.</p><div class="pr-drivers">${[{factor:'Model starting value',pointsTowardPick:ex.baselineTowardPick},...ex.drivers].map(d=>`<div><span>${esc(d.factor)}</span><b>${signed(d.pointsTowardPick)}</b></div>`).join('')}</div>`:''}<p>Game stats describe the result. They do not prove what caused the win.</p><a href="${esc(r.sourceArchive)}" target="_blank" rel="noreferrer">Saved prediction ↗</a>${r.sourceUrl?' · <a href="'+esc(r.sourceUrl)+'" target="_blank" rel="noreferrer">Final box score ↗</a>':''}</details></article>`;
  }
  function ledger(rows){const chosen=market==='upset'?rows.filter(r=>r.pickedUnderdog):rows;const labels={win:'Correct',loss:'Missed',push:'Push',no_pick:'No pick',unavailable:'No saved line'};
    $('prLedger').innerHTML=chosen.length?chosen.slice(0,limit).map(r=>{const result=outcome(r,market);return `<div class="pr-receipt"><div><small>${niceDate(easternDate(r.date))} · ${esc(shortConf(D.teams[r.home]?.conference||''))}</small><h4>${esc(name(r.away))} ${r.neutral?'vs.':'at'} ${esc(name(r.home))}</h4><p>Our pick: <b>${esc(selection(r,market))}</b></p><p class="pr-score">Final: ${esc(score(r))}${market==='total'?' · '+(r.homeScore+r.awayScore)+' total points':''}</p><details><summary>Saved pick & line</summary><p>Forecast: ${esc(stamp(r.forecastAt))}. ${r.archiveType==='recovered_saved_forecast'?'Recovered saved forecast.':'Daily archived forecast.'}</p><p>Model: ${r.pickedTeam?esc(name(r.pickedTeam))+' by '+Math.abs(r.predictedHomeMargin).toFixed(1):'Even'} · ${r.predictedTotal.toFixed(1)} combined points.</p><p>${r.quoteRetrievedAt?'Line checked '+esc(stamp(r.quoteRetrievedAt))+(r.quoteProvider?' · '+esc(r.quoteProvider):'')+'.':'No eligible pregame line saved.'}</p><a href="${esc(r.sourceArchive)}" target="_blank" rel="noreferrer">View saved forecast ↗</a></details></div><span class="pr-outcome ${result}">${labels[result]||'Not graded'}</span></div>`;}).join(''):'<p class="pr-empty">No saved picks match these filters.</p>';
    $('prMore').hidden=chosen.length<=limit;$('prMore').textContent=`Show more picks (${Math.min(limit,chosen.length)} of ${chosen.length})`;
  }
  function render(){
    const rows=filter(data.games,period,conference,query,D.teams),c=tally(rows,market),up=tally(rows,'upset');
    $('prMetrics').innerHTML=Object.keys(markets).map(k=>metric(rows,k)).join('');
    const days=rows.map(r=>easternDate(r.date)).sort();$('prCoverage').textContent=rows.length?`${rows.length} saved game${rows.length===1?'':'s'} · ${niceDate(days[0])}${days[0]===days.at(-1)?'':'–'+niceDate(days.at(-1))} · Dates in Eastern time`:'No saved games match these filters.';
    $('prUpsetRecord').textContent=`${up.win} outright wins · ${up.loss} misses from our underdog picks`;
    const wins=rows.filter(r=>r.pickedUnderdog&&r.upsetPickResult==='win');$('prUpsets').innerHTML=wins.length?wins.map(upsetCard).join(''):'<p class="pr-empty">No correct outright upset picks in this selection. An underdog covering the spread does not count here.</p>';
    $('prLedgerTitle').textContent=market==='upset'?'Every outright upset pick':`Every ${markets[market].toLowerCase()} pick`;
    $('prGrading').textContent=`${descriptions[market]} ${c.push} pushes (line ties). ${c.no_pick} no-picks.${market==='spread'||market==='total'?' '+c.unavailable+' games had no saved line and are excluded from the record.':''}`;
    document.querySelectorAll('[data-pr-market]').forEach(b=>{b.setAttribute('aria-pressed',String(b.dataset.prMarket===market));b.onclick=()=>{market=b.dataset.prMarket;limit=12;render();};});
    ledger(rows);
  }
  async function init(){await initialDataReady;if(!D)return;const mount=$('pickResults');
    try{const response=await fetch('daily-results.json',{cache:'no-cache'});if(!response.ok)throw Error('Results unavailable');data=await response.json();
      const weeks=[...new Set(data.games.map(r=>weekOf(r.date)))].sort().reverse(),days=[...new Set(data.games.map(r=>easternDate(r.date)))].sort().reverse(),conferences=[...new Set(data.games.flatMap(r=>[D.teams[r.home]?.conference,D.teams[r.away]?.conference]).filter(Boolean))].sort();
      mount.innerHTML=`<article class="pr-overview"><div class="eyebrow">THE DARKHORSE MODEL · PICK RECORD</div><h2>Our picks. The results.</h2><p>Who won. Who covered. Over or under. Every result below grades <b>our saved pick</b> against the final score.</p><div class="pr-filters"><label for="prPeriod">When<select id="prPeriod"><option value="all">All saved picks</option><optgroup label="By week">${weeks.map(w=>`<option value="week:${w}">Week of ${niceDate(w)}</option>`).join('')}</optgroup><optgroup label="By game day">${days.map(d=>`<option value="day:${d}">${niceDate(d)}</option>`).join('')}</optgroup></select></label><label for="prConference">Conference<select id="prConference"><option value="all">All conferences</option>${conferences.map(c=>`<option value="${esc(c)}">${esc(shortConf(c))}</option>`).join('')}</select></label><label for="prSearch">Find a team<input type="search" id="prSearch" placeholder="Kansas, LSU, USC…"></label></div><p id="prCoverage" class="tiny"></p><div id="prMetrics" class="pr-metrics"></div><p class="pr-footnote">Moneyline = pick the game winner. A push is a tie against the betting line; it is neither a win nor a loss. Includes older recovered forecast files. These are pick records, not dollar returns.</p></article><section class="pr-upset-section"><div class="pr-section-head"><div><div class="eyebrow">CALLED IT</div><h2>Upsets we called.</h2><p id="prUpsetRecord"></p></div><button type="button" id="prAllUpsets">See every upset pick ↓</button></div><p class="pr-footnote">We selected the underdog to win, and it won outright. The saved spread identifies the underdog. A high upset-meter reading alone is not a winning pick.</p><div id="prUpsets" class="pr-upset-grid"></div></section><article class="pr-ledger"><div class="eyebrow">CHECK THE RECEIPTS</div><h2 id="prLedgerTitle"></h2><div class="dh-switches">${Object.entries(markets).map(([k,v])=>`<button type="button" data-pr-market="${k}" aria-pressed="false">${v}</button>`).join('')}</div><p id="prGrading" class="tiny"></p><div id="prLedger"></div><button type="button" id="prMore">Show more</button></article><details class="pr-method"><summary>How this record is counted</summary><p>For each completed game, we use the latest saved main-model forecast generated before kickoff. Rebuilt historical tests are excluded. Older recovered forecast files are labeled in each receipt; their original publication time was not independently verified.</p><p>A moneyline pick selects the team with the higher predicted score. Spread picks compare the predicted margin with the saved point spread. Over/under picks compare the predicted combined score with the saved total. An exact model tie is no pick. Missing lines are excluded, never counted as wins.</p><p>Only a saved pregame line can define the spread, total or underdog. Quotes can have a different timestamp from the forecast; open a receipt to check both. No archived moneyline prices are available for these older games, so we do not claim payouts or profit.</p><p>Conference filters include a game if either team belongs to that conference; cross-conference games can appear in both groups. The cards and receipts share the same filters. Explanations use the saved main-model inputs. Final game stats are shown separately and cannot prove why a pick worked.</p><a href="daily-results.json" download>Download all graded picks</a></details>`;
      $('prPeriod').onchange=e=>{period=e.target.value;limit=12;render();};$('prConference').onchange=e=>{conference=e.target.value;limit=12;render();};$('prSearch').oninput=e=>{query=e.target.value.trim();limit=12;render();};$('prMore').onclick=()=>{limit+=20;render();};$('prAllUpsets').onclick=()=>{market='upset';limit=12;render();$('prLedgerTitle').scrollIntoView({behavior:'smooth',block:'start'});};render();
    }catch(error){mount.innerHTML='<article><h2>Pick results could not load.</h2><p>Reload to try again. No results are being estimated or substituted.</p></article>';console.error(error);}
  }
  document.addEventListener('DOMContentLoaded',()=>init().catch(console.error),{once:true});
  return api;
})();

